import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
const root = dirname(fileURLToPath(import.meta.url));
export function buildMigrationBundle() {
const migrations = readdirSync(join(root, "migrations")).filter(n => n.endsWith(".sql")).sort();
return ["-- Generated by node supabase/build-migration-bundle.mjs. No seed or credentials.",
  ...migrations.map(name => {
    const sql = readFileSync(join(root, "migrations", name), "utf8").replaceAll("\r\n", "\n").trim();
    return `-- Migration: ${name}\n` + (name.endsWith("idempotent_inspections.sql") ? sql : `BEGIN;\n${sql}\nCOMMIT;`);
  })].join("\n\n") + "\n";
}
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
writeFileSync(join(root, "apply-runtime.sql"), buildMigrationBundle());
console.log("Built supabase/apply-runtime.sql (migrations only; no development seed).");
}
